package report

import (
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strings"

	"github.com/Shironex/stackward/internal/catalog"
	"github.com/Shironex/stackward/internal/checks"
)

// CheckDocsBase is where each check has a stable page, docs/checks/<ID>.md,
// generated by cmd/docgen. It is the GitHub path rather than the docs site
// because the site address is not final; switch it here when it is.
const CheckDocsBase = "https://github.com/Shironex/stackward/blob/main/docs/checks/"

// MarkdownOptions tunes WriteMarkdown.
type MarkdownOptions struct {
	// Passing lists passing and skipped results too, not just counts.
	Passing bool
	// Untrusted renders every field the audited host supplied (version,
	// host, OS, kernel, collection time, sandbox and collector text,
	// messages) as code spans, so it can never become a link, an autolink,
	// HTML or a heading. Fleet reports set it: there the report came from
	// another machine.
	Untrusted bool
}

// mdText renders host supplied text for a report: escaped Markdown for a
// local report, a code span for an untrusted one. Empty text is "-".
type mdText func(string) string

func textRenderer(untrusted bool) mdText {
	if untrusted {
		return func(s string) string {
			if s == "" {
				return "-"
			}
			return codeSpan(s)
		}
	}
	return mdOrDash
}

// untrustedCell renders host supplied text for a table cell: a code span
// in which every pipe is replaced by U+2223 (a divides sign that looks
// alike). Escaping the pipe is not enough: a host can put its own
// backslash before it, the escape then escapes the backslash, and the pipe
// ends the cell, so the rest of the text would render as live Markdown.
func untrustedCell(s string) string {
	return textRenderer(true)(strings.ReplaceAll(s, "|", "\u2223"))
}

// levelOrder is the order findings are listed in within a group.
var levelOrder = map[checks.Level]int{
	checks.Fail: 0, checks.Warn: 1, checks.Unknown: 2, checks.Info: 3, checks.Pass: 4, checks.Skip: 5,
}

// WriteMarkdown writes the report as GitHub flavoured Markdown, meant for an
// issue or a handover note. It renders from the already redacted Report, so
// nothing here can bring a secret back; free text is escaped and evidence is
// kept inside code spans.
func WriteMarkdown(w io.Writer, r *Report, o MarkdownOptions) error {
	var b strings.Builder
	p := func(format string, a ...any) { fmt.Fprintf(&b, format, a...) }

	writeMarkdownHeader(&b, r, o.Untrusted)

	s := r.Summary
	p("\n## Summary\n\n| Level | Count |\n|---|---|\n")
	for _, row := range []struct {
		name string
		n    int
	}{{"fail", s.Fail}, {"warn", s.Warn}, {"unknown", s.Unknown}, {"info", s.Info}, {"pass", s.Pass}, {"skip", s.Skip}} {
		p("| %s | %d |\n", row.name, row.n)
	}
	if s.Accepted > 0 {
		p("| accepted | %d |\n", s.Accepted)
	}

	// Full sections only for what needs a decision; everything else is a
	// compact table so a mostly unknown run stays readable.
	var full, accepted, info, unknown, passing []Item
	for _, it := range r.Results {
		if it.Accepted() {
			accepted = append(accepted, it)
			continue
		}
		switch it.Level {
		case checks.Fail, checks.Warn:
			full = append(full, it)
		case checks.Info:
			info = append(info, it)
		case checks.Unknown:
			unknown = append(unknown, it)
		default:
			if o.Passing {
				passing = append(passing, it)
			}
		}
	}

	switch {
	case len(full) == 0 && len(accepted) > 0:
		p("\nNo open findings; %s below.\n", plural(len(accepted), "accepted finding is", "accepted findings are"))
	case len(full) == 0:
		p("\nNo findings.\n")
	}
	for _, g := range groupIDs(full) {
		items := byGroup(full, g)
		sort.SliceStable(items, func(i, j int) bool { return levelOrder[items[i].Level] < levelOrder[items[j].Level] })
		p("\n## %s: %s\n", mdEscape(g), mdEscape(catalog.GroupName(g)))
		for _, it := range items {
			writeMarkdownItem(&b, it, o.Untrusted)
		}
	}

	writeMarkdownWaivers(&b, accepted, WaiversToReview(r.Waivers))
	if len(info) > 0 {
		p("\n## Notes\n")
		writeCompact(&b, "", info, "Result", o.Untrusted)
	}
	if len(unknown) > 0 {
		p("\n## Not inspected\n\n")
		if n := NotRootNote(r); n != "" {
			p("%s.\n\n", mdEscape(strings.ToUpper(n[:1])+n[1:]))
		}
		writeCompact(&b, plural(len(unknown), "check not inspected", "checks not inspected"), unknown, "Reason", o.Untrusted)
	}
	if len(passing) > 0 {
		p("\n## Passing and skipped\n\n")
		writeCompact(&b, fmt.Sprintf("%d passing or skipped", len(passing)), passing, "Result", o.Untrusted)
	}

	p("\nExplain any check with `stackward explain <id>`.\n")
	_, err := io.WriteString(w, b.String())
	return err
}

// writeMarkdownHeader writes the title and the facts about the run: host,
// OS, profile, root, sandbox, coverage, waivers and the collectors that did
// not end ok. With untrusted, every host supplied value is a code span.
func writeMarkdownHeader(b *strings.Builder, r *Report, untrusted bool) {
	p := func(format string, a ...any) { fmt.Fprintf(b, format, a...) }
	txt := textRenderer(untrusted)
	version := mdEscape(r.Tool.Version)
	if untrusted {
		version = txt(r.Tool.Version)
	}
	p("# stackward %s audit\n\n", version)
	host := r.Host.HostnameHash
	if r.Host.Hostname != "" {
		host = r.Host.Hostname
	}
	p("- **Host:** %s\n", txt(host))
	p("- **OS:** %s, kernel %s\n", txt(strings.TrimSpace(r.Host.OS)), txt(r.Host.Kernel))
	p("- **Collected:** %s\n", txt(r.GeneratedAt))
	p("- **Profile:** %s (%s)\n", mdEscape(string(r.Profile.Name)), mdEscape(r.Profile.Source))
	p("- **Root:** %s\n", yesNo(r.Coverage.Root))
	sandboxText := mdEscape(sandboxLine(r.Coverage.Sandbox))
	if untrusted {
		sandboxText = txt(sandboxLine(r.Coverage.Sandbox))
	}
	p("- **Sandbox:** %s\n", sandboxText)
	p("- **Coverage:** %s, root: %s\n", CoverageLine(r.Coverage), yesNo(r.Coverage.Root))
	if l := WaiversLine(r.Waivers); l != "" {
		p("- **Waivers:** %s\n", l)
	}
	for _, c := range r.Coverage.Collectors {
		if c.Status == "ok" {
			continue
		}
		name, why := mdEscape(c.Name), mdEscape(joinNonEmpty(c.Reason, c.Error))
		if untrusted {
			name, why = txt(c.Name), txt(joinNonEmpty(c.Reason, c.Error))
		}
		p("- **Collector %s:** %s: %s\n", name, mdEscape(string(c.Status)), why)
	}
}

func writeMarkdownItem(b *strings.Builder, it Item, untrusted bool) {
	fmt.Fprintf(b, "\n### %s %s: [%s](%s%s.md) %s\n\n", strings.ToUpper(string(it.Level)), mdEscape(string(it.Severity)),
		it.ID, CheckDocsBase, it.ID, mdEscape(it.Title))
	fmt.Fprintf(b, "- **Subject:** %s\n", codeSpan(it.Subject))
	if it.Message != "" {
		msg := mdEscape(it.Message)
		if untrusted {
			msg = codeSpan(it.Message)
		}
		fmt.Fprintf(b, "- **Result:** %s\n", msg)
	}
	if it.Waiver != nil {
		fmt.Fprintf(b, "- **Waiver:** %s\n", mdEscape(AcceptedNote(it.Waiver)))
	}
	if it.Fix.Hint != "" && (it.Level == checks.Fail || it.Level == checks.Warn) {
		// The hint is catalog text and may carry its own code spans.
		hint := strings.ReplaceAll(it.Fix.Hint, "\n", " ")
		fmt.Fprintf(b, "- **Fix:** %s\n", hint)
	}
	if len(it.Evidence) == 0 {
		return
	}
	b.WriteString("\n<details><summary>Evidence</summary>\n\n")
	keys := make([]string, 0, len(it.Evidence))
	for k := range it.Evidence {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		fmt.Fprintf(b, "- %s: %s\n", codeSpan(k), codeSpan(evidenceText(it.Evidence[k])))
	}
	b.WriteString("\n</details>\n")
}

// evidenceText renders one evidence value: strings as they are, everything
// else as compact JSON.
func evidenceText(v any) string {
	if s, ok := v.(string); ok {
		return s
	}
	out, err := json.Marshal(v)
	if err != nil {
		return fmt.Sprint(v)
	}
	return string(out)
}

// codeSpan wraps s in a code span whose fence is longer than any backtick run
// inside it. Newlines become spaces and pipes are escaped, so it is also safe
// inside a table cell.
func codeSpan(s string) string {
	s = strings.NewReplacer("\r\n", " ", "\n", " ", "\r", " ").Replace(s)
	if s == "" {
		return "` `"
	}
	longest, run := 0, 0
	for _, c := range s {
		if c == '`' {
			run++
			if run > longest {
				longest = run
			}
		} else {
			run = 0
		}
	}
	fence := strings.Repeat("`", longest+1)
	pad := ""
	if strings.HasPrefix(s, "`") || strings.HasSuffix(s, "`") || strings.HasPrefix(s, " ") || strings.HasSuffix(s, " ") {
		pad = " "
	}
	return fence + pad + s + pad + fence
}

var mdReplacer = strings.NewReplacer(
	"\\", "\\\\", "`", "\\`", "*", "\\*", "_", "\\_", "[", "\\[", "]", "\\]",
	"<", "&lt;", ">", "&gt;", "|", "\\|", "#", "\\#", "!", "\\!", "~", "\\~",
	"\r\n", " ", "\n", " ", "\r", " ",
)

// mdEscape makes free text render literally: no emphasis, links, HTML,
// headings or table breaks.
func mdEscape(s string) string { return mdReplacer.Replace(s) }

func mdOrDash(s string) string {
	if s == "" {
		return "-"
	}
	return mdEscape(s)
}

func yesNo(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

func groupIDs(items []Item) []string {
	seen := map[string]bool{}
	var ids []string
	for _, it := range items {
		if !seen[it.Group] {
			seen[it.Group] = true
			ids = append(ids, it.Group)
		}
	}
	sort.Slice(ids, func(i, j int) bool { return catalog.GroupRank(ids[i]) < catalog.GroupRank(ids[j]) })
	return ids
}

func byGroup(items []Item, g string) []Item {
	var out []Item
	for _, it := range items {
		if it.Group == g {
			out = append(out, it)
		}
	}
	return out
}

// writeCompact writes one table per group inside a collapsed details block.
// An empty summary writes the tables without the details wrapper.
func writeCompact(b *strings.Builder, summary string, items []Item, reasonHead string, untrusted bool) {
	if summary != "" {
		fmt.Fprintf(b, "<details><summary>%s</summary>\n", summary)
	}
	for _, g := range groupIDs(items) {
		fmt.Fprintf(b, "\n**%s: %s**\n\n| Check | Title | Subject | %s |\n|---|---|---|---|\n", mdEscape(g), mdEscape(catalog.GroupName(g)), reasonHead)
		for _, it := range byGroup(items, g) {
			reason := it.Message
			if reason == "" {
				reason = string(it.Level)
			}
			fmt.Fprintf(b, "| [%s](%s%s.md) | %s | %s | %s |\n", it.ID, CheckDocsBase, it.ID, mdEscape(it.Title),
				subjectCell(it.Subject, untrusted), reasonCell(reason, untrusted))
		}
	}
	if summary != "" {
		b.WriteString("\n</details>\n")
	}
}

// reasonCell renders a compact table's reason: escaped for a local report,
// a code span for an untrusted one.
func reasonCell(reason string, untrusted bool) string {
	if untrusted {
		return untrustedCell(reason)
	}
	return mdEscape(reason)
}

// subjectCell renders a compact table's subject as a code span; in an
// untrusted report its pipes are replaced, not escaped (untrustedCell).
func subjectCell(subject string, untrusted bool) string {
	if untrusted {
		return untrustedCell(subject)
	}
	return strings.ReplaceAll(codeSpan(subject), "|", "\\|")
}

func plural(n int, one, many string) string {
	if n == 1 {
		return "1 " + one
	}
	return fmt.Sprintf("%d %s", n, many)
}

// writeMarkdownWaivers writes the findings a waiver accepts, shown with
// their real level, reason and expiry, and the waivers that did not apply.
func writeMarkdownWaivers(b *strings.Builder, accepted []Item, review []WaiverEntry) {
	if len(accepted) > 0 {
		b.WriteString("\n## Accepted\n\nFindings a waiver accepts until it expires. The level and evidence are the real ones.\n\n")
		b.WriteString("| Check | Level | Subject | Result | Reason | Until |\n|---|---|---|---|---|---|\n")
		for _, it := range accepted {
			fmt.Fprintf(b, "| [%s](%s%s.md) | %s %s | %s | %s | %s | %s |\n", it.ID, CheckDocsBase, it.ID,
				it.Level, mdEscape(string(it.Severity)), strings.ReplaceAll(codeSpan(it.Subject), "|", "\\|"),
				mdEscape(Headline(it)), mdEscape(it.Waiver.Reason), mdEscape(it.Waiver.Expires))
		}
	}
	if len(review) > 0 {
		b.WriteString("\n## Waivers to review\n\n| Check | Subject | Problem | Reason |\n|---|---|---|---|\n")
		for _, w := range review {
			fmt.Fprintf(b, "| %s | %s | %s | %s |\n", mdEscape(w.Check), strings.ReplaceAll(codeSpan(w.Subject), "|", "\\|"),
				mdEscape(WaiverProblem(w)), mdEscape(w.Reason))
		}
	}
}
